/**
 * knowledgeBase.js
 * Unified knowledge store for GateNexa Insights Hub.
 * 
 * Consumes build-time generated gateKnowledge.json.
 * Provides typed getters for UI components.
 * 
 * Source of truth: resources/GATE_KNOWLEDGE_BASE.md + resources/insights.txt
 * Generated by: scripts/buildKnowledgeBase.mjs
 */

import gateKnowledgeData from './generated/gateKnowledge.json';

// ─── Raw Data ─────────────────────────────────────────────────────────

export const { metadata } = gateKnowledgeData;

// ─── Typed Getters ────────────────────────────────────────────────────

export const insights = gateKnowledgeData.entries.filter(e => e.type === 'insight');
export const qaItems = gateKnowledgeData.entries.filter(e => e.type === 'qa');
export const decisionFrameworks = gateKnowledgeData.entries.filter(e => e.type === 'decision-framework');
export const subjectInsights = gateKnowledgeData.entries.filter(e => e.type === 'subject');
export const roiTopics = gateKnowledgeData.entries.filter(e => e.type === 'roi-topic');
export const mistakes = gateKnowledgeData.entries.filter(e => e.type === 'mistake');
export const revisionMethods = gateKnowledgeData.entries.filter(e => e.type === 'revision');
export const testingStrategies = gateKnowledgeData.entries.filter(e => e.type === 'testing');
export const roadmaps = gateKnowledgeData.entries.filter(e => e.type === 'roadmap');
export const knowledgeGraph = gateKnowledgeData.entries.filter(e => e.type === 'knowledge-graph');
export const trackers = gateKnowledgeData.entries.filter(e => e.type === 'tracker');
export const crossSourceIntel = gateKnowledgeData.entries.filter(e => e.type === 'cross-source');

// insights.txt derived types
export const subjectInsightsFromTxt = gateKnowledgeData.entries.filter(e => e.type === 'subject-insight');
export const resourceSummaries = gateKnowledgeData.entries.filter(e => e.type === 'resource-summary');
export const timelines = gateKnowledgeData.entries.filter(e => e.type === 'timeline');
export const studyMethods = gateKnowledgeData.entries.filter(e => e.type === 'study-method');
export const generalInsights = gateKnowledgeData.entries.filter(e => e.type === 'general-insight');
export const mistakePrevention = gateKnowledgeData.entries.filter(e => e.type === 'mistake-prevention');
export const testingInsights = gateKnowledgeData.entries.filter(e => e.type === 'testing-insight');
export const strategiesFromTxt = gateKnowledgeData.entries.filter(e => e.type === 'strategy');

// ─── Filtered Getters ─────────────────────────────────────────────────

/** ROI topics by priority tier */
export const roiByTier = {
  tier1: roiTopics.filter(t => t.priority === 'Tier 1'),
  tier2: roiTopics.filter(t => t.priority === 'Tier 2'),
  tier3: roiTopics.filter(t => t.priority === 'Tier 3'),
};

/** Insights grouped by category */
export const insightsByCategory = insights.reduce((acc, item) => {
  (acc[item.category] = acc[item.category] || []).push(item);
  return acc;
}, {});

/** Q&A items grouped by category */
export const qaByCategory = qaItems.reduce((acc, item) => {
  (acc[item.category] = acc[item.category] || []).push(item);
  return acc;
}, {});

/** Mistakes grouped by category */
export const mistakesByCategory = mistakes.reduce((acc, item) => {
  (acc[item.category] = acc[item.category] || []).push(item);
  return acc;
}, {});

/** Subject insights keyed by subject name */
export const subjectByName = subjectInsights.reduce((acc, item) => {
  acc[item.subject] = item;
  return acc;
}, {});

/** Roadmaps keyed by type */
export const roadmapByType = roadmaps.reduce((acc, item) => {
  acc[item.roadmapType] = item;
  return acc;
}, {});

/** Knowledge graph edges (prerequisite relationships) */
export const prerequisiteEdges = knowledgeGraph.filter(e =>
  e.type === 'knowledge-graph' && e.requires
);

/** Knowledge graph interconnections */
export const interconnections = knowledgeGraph.filter(e =>
  e.type === 'knowledge-graph' && e.appearsIn
);

// ─── Search Helpers ───────────────────────────────────────────────────

/**
 * Full-text search across all entries.
 * Returns entries matching query in title, content, question, answer, subject, tags, or sourceSection.
 */
export function searchKnowledgeBase(query, options = {}) {
  const { types, categories, limit = 100 } = options;
  const q = query.toLowerCase().trim();
  if (!q) return [];

  let candidates = gateKnowledgeData.entries;
  if (types && types.length > 0) {
    candidates = candidates.filter(e => types.includes(e.type));
  }
  if (categories && categories.length > 0) {
    candidates = candidates.filter(e => categories.includes(e.category));
  }

  return candidates
    .map(entry => {
      const searchText = [
        entry.title,
        entry.content,
        entry.question,
        entry.answer,
        entry.subject,
        entry.sourceSection,
        ...(entry.tags || []),
      ].filter(Boolean).join(' ').toLowerCase();

      if (!searchText.includes(q)) return null;

      // Simple relevance score
      let score = 0;
      if (entry.title?.toLowerCase().includes(q)) score += 10;
      if (entry.question?.toLowerCase().includes(q)) score += 8;
      if (entry.tags?.some(t => t.toLowerCase().includes(q))) score += 5;
      if (entry.content?.toLowerCase().includes(q)) score += 3;
      if (entry.sourceSection?.toLowerCase().includes(q)) score += 2;

      return { entry, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(r => r.entry);
}

/**
 * Get entries by tag
 */
export function getByTag(tag) {
  const t = tag.toLowerCase();
  return gateKnowledgeData.entries.filter(e =>
    e.tags?.some(et => et.toLowerCase() === t)
  );
}

/**
 * Get related entries (same tags, excluding self)
 */
export function getRelated(entryId, limit = 5) {
  const entry = gateKnowledgeData.entries.find(e => e.id === entryId);
  if (!entry) return [];

  return gateKnowledgeData.entries
    .filter(e => e.id !== entryId)
    .map(e => {
      const commonTags = (e.tags || []).filter(t => entry.tags?.includes(t));
      return { entry: e, relevance: commonTags.length };
    })
    .filter(r => r.relevance > 0)
    .sort((a, b) => b.relevance - a.relevance)
    .slice(0, limit)
    .map(r => r.entry);
}

/**
 * Get summary statistics for display
 */
export function getStats() {
  return {
    totalEntries: metadata.totalCount,
    byType: { ...metadata.byType },
    bySource: { ...metadata.bySource },
    byCategory: { ...metadata.byCategory },
    generatedAt: metadata.generatedAt,
  };
}

// ─── Unified API ──────────────────────────────────────────────────────

/**
 * Get all knowledge entries
 */
export function getAllKnowledge() {
  return gateKnowledgeData.entries;
}

/**
 * Get entries by type
 */
export function getKnowledgeByType(type) {
  return gateKnowledgeData.entries.filter(e => e.type === type);
}

/**
 * Get entries by category
 */
export function getKnowledgeByCategory(category) {
  return gateKnowledgeData.entries.filter(e => e.category === category);
}

/**
 * Get entries by subject
 */
export function getKnowledgeBySubject(subject) {
  const s = subject.toLowerCase();
  return gateKnowledgeData.entries.filter(e =>
    e.subject?.toLowerCase() === s ||
    e.relatedSubjects?.some(rs => rs.toLowerCase() === s)
  );
}

/**
 * Get knowledge counts by type
 */
export function getKnowledgeCounts() {
  return { ...metadata.byType };
}
